questionvariables.text:
/* Fixed: one specific proof. Correct openings in positions 2 and 5. */
opts1: [
 [oB, false, "Let the two odd numbers be \\(2k + 1\\) and \\(2k + 1\\), where \\(k\\) is an integer."],
 [oA, true, "Let the two odd numbers be \\(2k + 1\\) and \\(2m + 1\\), where \\(k\\) and \\(m\\) are integers."],
 [oE, false, "Let the two odd numbers be 3 and 5; any other pair of odd numbers works in the same way."],
 [oF, false, "Let \\(a\\) and \\(b\\) be odd numbers. Then \\(a = 2k + 1\\) and \\(b = 2m + 1\\) for all integers \\(k\\) and \\(m\\)."],
 [oD, true, "Let \\(a\\) and \\(b\\) be odd numbers. Then \\(a = 2k + 1\\) and \\(b = 2m + 1\\) for some integers \\(k\\) and \\(m\\)."],
 [oC, false, "Let the two odd numbers be \\(2k + 1\\) and \\(2k + 3\\), where \\(k\\) is an integer."]
];
ta2: 2*k*m - k - m;
/* Diagnostics: did not halve; signs carried over from 2k + 1 and 2m + 1. */
dhalf: 4*k*m - 2*k - 2*m;
dplus: 2*k*m + k + m;
/* Validators run with simp:false, so simplify explicitly. */
validate_km(ex) := block([e], e: ev(expand(ex), simp),
  if equationp(ex) then "Type the expression for \\(M\\) only, without M = in front."
  else if not(every(lambda([v], member(v, [k, m])), listofvars(ex))) then "Use only the letters \\(k\\) and \\(m\\), with * between letters that are multiplied: type k*m, not km."
  else if not(polynomialp(e, [k, m])) then "Enter a polynomial in \\(k\\) and \\(m\\), such as 3*k*m - m. Put * before a bracket: type m*(k + 3), not m(k + 3)."
  else "");
